    match self.column_max_split {
        Some(max_split) => separator
            .splitn(s, max_split)
            .filter(|x| !(self.collapse_empty && x.is_empty()))
            .collect(),
        None => separator
            .split(s)
            .filter(|x| !(self.collapse_empty && x.is_empty()))
            .collect(),
    }
}

